CREATE TABLE IF NOT EXISTS order_processing (order_id VARCHAR(64) PRIMARY KEY, accepted_event_id VARCHAR(64) NOT NULL UNIQUE, customer_id VARCHAR(128) NOT NULL, product VARCHAR(255) NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), amount DECIMAL(19,2) NOT NULL CHECK(amount>0), status VARCHAR(24) NOT NULL, received_at TIMESTAMP WITH TIME ZONE NOT NULL, processed_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE IF NOT EXISTS consumed_events(event_id VARCHAR(64) PRIMARY KEY,event_type VARCHAR(64) NOT NULL,consumed_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE IF NOT EXISTS outbox_events(id VARCHAR(64) PRIMARY KEY,aggregate_id VARCHAR(64) NOT NULL,event_type VARCHAR(64) NOT NULL,payload CLOB NOT NULL,correlation_id VARCHAR(64) NOT NULL,state VARCHAR(16) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,published_at TIMESTAMP WITH TIME ZONE,retry_count INTEGER NOT NULL DEFAULT 0,last_error VARCHAR(1000));
CREATE INDEX IF NOT EXISTS idx_processing_outbox_state_created ON outbox_events(state,created_at);
